  it('失败结果：头部为失败形态、卡片呈失败配色（bg-fail-bg）', () => {
    renderConversation([
      {
        ...base(0),
        kind: 'runResult',
        subtype: 'error_max_turns',
        isError: true,
        numTurns: 9,
